add_filter( 'woocommerce_checkout_registration_required', 'perfectpixel_guest_existing_registration_required' );
add_action( 'woocommerce_checkout_create_order', 'perfectpixel_guest_existing_assign', 10, 2 );
add_filter( 'woocommerce_checkout_update_customer_data', 'perfectpixel_guest_existing_no_profile_update', 10, 2 );

function perfectpixel_guest_existing_user_id() {
	if ( is_user_logged_in() || empty( $_POST['billing_email'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification
		return 0;
	}
	return (int) email_exists( sanitize_email( wp_unslash( $_POST['billing_email'] ) ) ); // phpcs:ignore WordPress.Security.NonceVerification
}

function perfectpixel_guest_existing_registration_required( $required ) {
	if ( perfectpixel_guest_existing_user_id() ) {
		unset( $_POST['createaccount'] );
		return false;
	}
	return $required;
}

function perfectpixel_guest_existing_assign( $order, $data ) {
	$user_id = perfectpixel_guest_existing_user_id();
	if ( $user_id ) {
		$order->set_customer_id( $user_id );
	}
}

function perfectpixel_guest_existing_no_profile_update( $update, $checkout ) {
	return perfectpixel_guest_existing_user_id() ? false : $update;
}
